STUB_TEMPLATE = '''"""{purpose}

Spec: {spec}. Pure-Python, NautilusTrader-free (composed by strategy/convexity_strategy.py).
See docs/ARCHITECTURE.md for the package layout and docs/BUILD_PLAN.md for the build order.
"""

# TODO(impl): implement per {spec}. Shared boundary types live in convexity.core.types;
# governance buckets + the resolve_config single-merge-point pattern in convexity.core.params.
'''


def main() -> None:
    created, skipped = 0, 0
    for rel, spec, purpose in STUBS:
        path = SRC / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists() and "TODO(impl)" not in path.read_text() and path.stat().st_size > 0:
            skipped += 1
            continue
        path.write_text(STUB_TEMPLATE.format(spec=spec, purpose=purpose))
        created += 1
    print(f"scaffold: {created} stub files written, {skipped} skipped (already implemented)")


if __name__ == "__main__":
    main()
